{
  "objective": "Build a dependency-free command-line utility that reads one local UTF-8 text file and writes deterministic word and line counts.",
  "requirements": [
    {
      "id": "R1",
      "requirement": "Accept exactly one positional argument identifying a local text file.",
      "source": "User request: reads a local UTF-8 text file."
    },
    {
      "id": "R2",
      "requirement": "Decode the file as strict UTF-8 and reject malformed input without emitting partial counts.",
      "source": "User request: UTF-8 text file."
    },
    {
      "id": "R3",
      "requirement": "Use only Python 3.11 or later and its standard library; require no third-party packages.",
      "source": "User request: dependency-free command-line utility; runtime choice is an explicit planning assumption."
    },
    {
      "id": "R4",
      "requirement": "Write word and line counts in a fixed format with consistent behavior across repeated runs and host platforms.",
      "source": "User request: writes deterministic word and line counts."
    },
    {
      "id": "R5",
      "requirement": "Provide observable acceptance criteria, scoped implementation responsibilities, independent verification, and review.",
      "source": "User request: acceptance criteria, scoped assignments, independent verification and review requirements."
    }
  ],
  "assumptions": [
    "Python 3.11 or later is already installed; dependency-free means no additional packages.",
    "A word is a maximal nonempty sequence separated by ASCII space, tab, carriage return, line feed, vertical tab, or form feed. Other Unicode characters, including nonbreaking spaces, remain part of words.",
    "A line ends at LF, CRLF, or a lone CR. CRLF counts as one terminator. A nonempty trailing segment without a terminator counts as one line.",
    "An empty file has zero words and zero lines.",
    "One initial UTF-8 byte order mark is ignored. Any subsequent U+FEFF character is ordinary content.",
    "The file remains unchanged while it is read.",
    "Output goes to standard output; no output file is created.",
    "Only regular files are supported; directories and special files are rejected."
  ],
  "acceptance": [
    {
      "id": "A1",
      "criterion": "An empty file produces exactly \"words=0 lines=0\\n\" and exit status 0."
    },
    {
      "id": "A2",
      "criterion": "The text \"alpha beta\\ngamma\\n\" produces exactly \"words=3 lines=2\\n\"."
    },
    {
      "id": "A3",
      "criterion": "The text \"alpha beta\" without a final terminator produces exactly \"words=2 lines=1\\n\"."
    },
    {
      "id": "A4",
      "criterion": "The text \"a\\r\\nb\\rc\\n\" produces exactly \"words=3 lines=3\\n\"."
    },
    {
      "id": "A5",
      "criterion": "The text \" \\t\\n\\n\" produces exactly \"words=0 lines=2\\n\"."
    },
    {
      "id": "A6",
      "criterion": "Two tokens separated only by a nonbreaking space count as one word; accented letters and emoji decode successfully."
    },
    {
      "id": "A7",
      "criterion": "An initial byte order mark does not change counts; a file containing only that mark produces zero words and zero lines."
    },
    {
      "id": "A8",
      "criterion": "Malformed UTF-8, an unreadable path, or a nonregular file produces no standard output, one fixed diagnostic line on standard error, and exit status 1."
    },
    {
      "id": "A9",
      "criterion": "Missing or extra arguments produce no standard output, a fixed usage diagnostic on standard error, and exit status 2."
    },
    {
      "id": "A10",
      "criterion": "Repeated runs over identical bytes produce identical output bytes, using LF even on platforms with another native line ending."
    }
  ],
  "assignments": [
    {
      "id": "implementation",
      "scope": "Implement decoding, counting, argument handling, fixed diagnostics, and concise behavioral documentation.",
      "allowed_paths": [
        "wordcount.py",
        "README.md"
      ],
      "interfaces": [
        "Counting interface: decoded text in; a pair of nonnegative integers representing words and lines out.",
        "CLI interface: exactly one local file path in; ASCII output \"words=<decimal> lines=<decimal>\\n\" on success.",
        "Failure interface: no count output; exit status 1 for input failures and 2 for argument failures.",
        "Document exact diagnostic text and all counting rules before verification."
      ],
      "dependencies": [
        "Approved requirements and assumptions in this plan."
      ]
    },
    {
      "id": "verification",
      "scope": "Independently author standard-library tests and a review record against the documented contract, without modifying implementation files.",
      "allowed_paths": [
        "tests/test_wordcount.py",
        "tests/fixtures/",
        "review.md"
      ],
      "interfaces": [
        "Exercise the public CLI with temporary local fixtures and inspect output bytes and exit status.",
        "Derive expected counts manually from this plan rather than importing the implementation's counting logic.",
        "Record requirement coverage, defects, and review findings in review.md."
      ],
      "dependencies": [
        "Implementation interface contract for test preparation.",
        "Completed implementation for execution and final review."
      ]
    }
  ],
  "dependencies": [
    {
      "consumer": "implementation",
      "prerequisite": "Available supported Python runtime and agreed counting semantics."
    },
    {
      "consumer": "verification",
      "prerequisite": "Stable CLI contract; fixture and expected-result preparation can proceed before implementation is complete."
    },
    {
      "consumer": "integration",
      "prerequisite": "Completed implementation, independent acceptance results, and resolved blocking review findings."
    }
  ],
  "integration_strategy": "Keep the utility in one module and the independently maintained tests in a separate directory. Establish the CLI contract first, implement counting and error handling, then run the independent suite against the integrated utility. Return failures to the implementation owner, preserve tests that expose defects, and repeat affected checks after corrections. Finish with the full acceptance suite and documentation consistency review.",
  "verification_requirements": [
    "Use only standard-library test facilities and temporary local files.",
    "Verify every acceptance criterion with explicitly recorded expected output bytes and exit status.",
    "Cover empty input, blank lines, trailing terminators, all supported line endings, ASCII separators, Unicode content, byte order marks, malformed UTF-8, and argument failures.",
    "Verify input bytes remain unchanged after successful and failed reads.",
    "Check deterministic output on available supported platforms; record any untested platforms as a verification limitation.",
    "Have a verifier other than the implementation author assess results without relying on implementation-derived expected values."
  ],
  "review_requirements": [
    "An independent reviewer checks requirement-to-test traceability and whether expected results follow the stated semantics.",
    "Inspect strict decoding, CRLF handling, final unterminated lines, initial byte order mark handling, and error paths for boundary mistakes.",
    "Confirm no third-party dependencies and no writes to the input file.",
    "Confirm diagnostics are fixed and platform exception text cannot alter the public output contract.",
    "Check documentation matches actual behavior and all changes remain within assignment allowed_paths.",
    "Resolve correctness defects before acceptance and explicitly record any remaining nonblocking limitations."
  ]
}
